int validate_memory_range(struct rxe_mem *mem, u64 iova, size_t length) {
    if (!mem)
        return -EFAULT;

    switch (mem->type) {
        case MEM_TYPE_DMA:
            return 0;
        case MEM_TYPE_MR:
        case MEM_TYPE_FMR:
            if (iova < mem->start || (iova + length) > (mem->start + mem->length))
                return -EFAULT;
            break;
        default:
            return -EFAULT;
    }

    return 0;
}

int rxe_check_mem_range(struct rxe_mem* mem, u64 iova, size_t length) {
    if (mem->type == RXE_MEM_TYPE_DMA)
        return 0;

    if (mem->type == RXE_MEM_TYPE_MR || mem->type == RXE_MEM_TYPE_FMR) {
        if (iova < mem->iova_start || length > mem->length)
            return -EFAULT;
        return 0;
    }

    return -EFAULT;
}

